WITH metrics AS (SELECT id, order_id, amount, paid_at, status, MIN(amount) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_amount, SUM(amount) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_amount, MAX(amount) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_amount, AVG(amount) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_amount FROM payments) SELECT s.id, s.order_id, s.paid_at, s.status, s.last4_sum_amount, CASE WHEN status RLIKE '^(SUCCESS|REFUNDED)$' THEN 'EXTENDED' WHEN status RLIKE '^(FAILED)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS status_zone, (SELECT MAX(x.unit_price) FROM order_items x WHERE x.order_id = s.order_id) AS max_order_item_unit_price FROM metrics s;
